      nativeTry: "__nativeTry",
      nativeDispatch: "__nativeDispatch",
      nativeFailureValue: "__nativeValue",
      raise: "__nativeRethrow",
      $effect: "__nativeEffect",
      $cleanup: "__nativeCleanup"
    };
